// Regenerate lib/tools/definitions.generated.mjs from a captured request.
//
// The 44 tool definitions are the client's own: the server compares the shape
// it receives, so a definition that was retyped — a reordered key, a dropped
// "required", a description with one word changed — is not a cosmetic
// difference, it is a request the vendor may answer differently. This script
// therefore copies the capture verbatim instead of transcribing it, and writes
// the sha256 of the serialised array beside it so a later hand edit to the
// generated file has something to disagree with.
//
//   node scripts/gen-tool-catalog.mjs [capture.json]
//   node scripts/gen-tool-catalog.mjs --check [capture.json]
//
// The capture defaults to the one taken from the Codar client and kept in
// register-machine's docs; point CODAR_TOOLS_CAPTURE at another file to use a
// newer one. Only the shape is read — nothing here contacts the network.
//
// Exit codes, so a caller can tell the failures apart:
//   0  wrote the file, or (--check) the file already is what the capture says
//   1  --check only: the file is out of date, or missing
//   2  the capture could not be read or does not look like a tools array;
//      nothing usable came of the run

import { createHash } from "node:crypto"
import { existsSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs"
import { dirname, join, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const HERE = dirname(fileURLToPath(import.meta.url))

export const OUT_PATH = join(HERE, "..", "lib", "tools", "definitions.generated.mjs")

const DEFAULT_CAPTURE = join(
  "D:", "project_GIT", "register-machine", "docs", "codar", "samples", "chat-completions.tools.json"
)

// The serialised form the test pins: two-space JSON, which is also what the
// capture file itself contains, so the hash is the capture's own.
const serialise = (tools) => JSON.stringify(tools, null, 2)

const sha256 = (text) => createHash("sha256").update(text, "utf8").digest("hex")

// CHUNK is how much of the capture one line of the generated file carries.
// A single 64 KB string literal is unreadable in a diff and unfindable with
// grep; splitting it keeps "which tool says this" answerable by opening the
// file and reading, while the array is still joined back into the exact bytes.
const CHUNK = 512

const chunks = (text) => {
  const points = Array.from(text)
  const out = []
  for (let i = 0; i < points.length; i += CHUNK) out.push(points.slice(i, i + CHUNK).join(""))
  return out
}

const header = (tools, digest) => `// Generated by scripts/gen-tool-catalog.mjs — do not edit by hand.
//
// The ${tools.length} tool definitions the Codar client sends, copied verbatim from
// the captured request body, plus the sha256 of their serialised form
// (JSON.stringify(definitions, null, 2)). test/tools.test.mjs pins that hash
// against a literal taken from the same capture, so an edit here that changes
// a byte fails the suite instead of quietly shipping a different request shape.
//
// Serialised sha256: ${digest}
// Regenerate with: node scripts/gen-tool-catalog.mjs
`

const render = (tools) => {
  const text = serialise(tools)
  const digest = sha256(text)
  const body = chunks(text).map((part) => `  ${JSON.stringify(part)}`).join(",\n")
  return [
    header(tools, digest),
    `export const TOOL_DEFINITIONS_SHA256 = ${JSON.stringify(digest)}`,
    "",
    "// The capture's own bytes, in pieces so the file can be read and searched.",
    "const SOURCE = [",
    body,
    '].join("")',
    "",
    "export const TOOL_DEFINITIONS = JSON.parse(SOURCE)",
    ""
  ].join("\n")
}

const readCapture = (path) => {
  const text = readFileSync(path, "utf8")
  const tools = JSON.parse(text)
  if (!Array.isArray(tools) || tools.length === 0) throw new Error("the capture is not a non-empty array")
  tools.forEach((entry, i) => {
    if (entry?.type !== "function") throw new Error(`entry ${i} is not type=function`)
    if (typeof entry.function?.name !== "string") throw new Error(`entry ${i} has no function.name`)
    if (typeof entry.function?.description !== "string") throw new Error(`entry ${i} has no function.description`)
    if (entry.function?.parameters?.type !== "object") throw new Error(`entry ${i} has no object parameters`)
  })
  return tools
}

// writeAtomic keeps a half-written generated file from replacing a working one:
// the rename either happens or it does not.
const writeAtomic = (path, text) => {
  mkdirSync(dirname(path), { recursive: true })
  const tmp = `${path}.${process.pid}.tmp`
  try {
    writeFileSync(tmp, text, "utf8")
    renameSync(tmp, path)
  } catch (error) {
    try {
      unlinkSync(tmp)
    } catch {}
    throw error
  }
}

const main = () => {
  const args = process.argv.slice(2)
  const check = args.includes("--check")
  const named = args.find((a) => !a.startsWith("--"))
  const path = resolve(named ?? process.env.CODAR_TOOLS_CAPTURE ?? DEFAULT_CAPTURE)

  let tools
  try {
    tools = readCapture(path)
  } catch (error) {
    console.error(`gen-tool-catalog: cannot read the capture at ${path}（${error.message}）`)
    return 2
  }

  const text = render(tools)
  if (check) {
    if (!existsSync(OUT_PATH)) {
      console.error("gen-tool-catalog: definitions.generated.mjs is missing")
      return 1
    }
    if (readFileSync(OUT_PATH, "utf8") !== text) {
      console.error("gen-tool-catalog: definitions.generated.mjs is out of date")
      return 1
    }
    console.log(`gen-tool-catalog: up to date（${tools.length} tools）`)
    return 0
  }

  writeAtomic(OUT_PATH, text)
  console.log(`gen-tool-catalog: wrote ${OUT_PATH}（${tools.length} tools, sha256 ${sha256(serialise(tools))}）`)
  return 0
}

process.exitCode = main()
